// Keeps only items at or below their reorder point. Everything else is dropped
// here, so the digest never lists an item that does not need ordering.
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const stock = Number(p.stock);
  const point = Number(p.reorder_point);
  if (!Number.isFinite(stock) || !Number.isFinite(point)) continue;
  if (stock > point) continue;
  const use = Number(p.daily_usage);
  const days = Number.isFinite(use) && use > 0 ? Math.floor(stock / use) : null;
  out.push({ json: {
    sku: String(p.sku || '').trim(),
    item: String(p.item || '').trim(),
    supplier: String(p.supplier || '').trim() || 'Unassigned',
    stock: stock,
    reorder_point: point,
    days_left: days,
    shortfall: point - stock
  }});
}
// Fewest days of stock first: that is the order you actually order in.
out.sort(function (a, b) {
  const da = a.json.days_left === null ? 9999 : a.json.days_left;
  const db = b.json.days_left === null ? 9999 : b.json.days_left;
  return da - db;
});
return out;

// One message, not one per item. A burst of Telegram sends gets rate-limited,
// and a single digest is what a person can actually act on at 07:00.
const cfg = $('CONFIG').first().json;
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length === 0) {
  return [{ json: { needs_alert: false, chat_id: cfg.chat_id, text: '' } }];
}
const baris = rows.map(function (r) {
  const hari = r.days_left === null ? 'no usage data' : r.days_left + 'd left';
  return '- ' + r.item + ' (' + r.sku + ') ' + r.stock + '/' + r.reorder_point + ', ' + hari;
});
const teks = 'Low stock: ' + rows.length + ' item' + (rows.length === 1 ? '' : 's') + '\n' + baris.join('\n');
return [{ json: { needs_alert: true, chat_id: cfg.chat_id, text: teks } }];
